export interface QueueState {
  readonly trackIds: string[];
  readonly index: number;
  readonly playing: boolean;
}

export type QueueAction =
  | { readonly type: "toggle" }
  | { readonly type: "next" }
  | { readonly type: "previous" }
  | { readonly type: "select"; readonly index: number };

export function makeQueueState(trackIds: readonly string[]): QueueState {
  if (trackIds.some(id => id === "")) throw new RangeError("Invalid track ID");
  return { trackIds: [...trackIds], index: trackIds.length === 0 ? -1 : 0, playing: false };
}

export function transitionQueue(state: QueueState, action: QueueAction): QueueState {
  const length = state.trackIds.length;
  const validIndex = length === 0
    ? state.index === -1
    : Number.isInteger(state.index) && state.index >= 0 && state.index < length;
  if (!validIndex || state.trackIds.some(id => id === "")) throw new RangeError("Invalid queue state");

  let index = state.index;
  let playing = state.playing;
  if (action.type === "toggle") {
    playing = !playing;
  } else if (length > 0 && action.type === "next") {
    index = (index + 1) % length;
  } else if (length > 0 && action.type === "previous") {
    index = index === 0 ? 0 : index - 1;
  } else if (length > 0 && action.type === "select" &&
             Number.isInteger(action.index) && action.index >= 0 && action.index < length) {
    index = action.index;
  }
  return { trackIds: [...state.trackIds], index, playing };
}
