import { makeQueueState, QueueState, transitionQueue } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}
function rangeError(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) {
    assert(error instanceof RangeError, `${message}: wrong error type`);
    return;
  }
  throw new Error(`${message}: did not throw`);
}

const input = ["a", "b", "a"];
const made = makeQueueState(input);
equal(made, { trackIds: ["a", "b", "a"], index: 0, playing: false }, "nonempty initial state");
assert(made.trackIds !== input, "makeQueueState aliases input array");
input[0] = "changed";
assert(made.trackIds[0] === "a", "caller mutation changed state");
equal(makeQueueState([]), { trackIds: [], index: -1, playing: false }, "empty initial state");
rangeError(() => makeQueueState(["ok", ""]), "empty track ID");

const state: QueueState = { trackIds: ["a", "b", "c"], index: 0, playing: false };
const previous = transitionQueue(state, { type: "previous" });
assert(previous.index === 2, "previous must wrap from first to last");
assert(previous.trackIds !== state.trackIds, "transition must allocate track array");
assert(state.index === 0 && !state.playing, "transition mutated state");
assert(transitionQueue({ ...state, index: 2 }, { type: "next" }).index === 0, "next must wrap from last to first");
assert(transitionQueue(state, { type: "toggle" }).playing, "toggle starts playback");
assert(!transitionQueue({ ...state, playing: true }, { type: "toggle" }).playing, "toggle stops playback");
assert(transitionQueue(state, { type: "select", index: 2 }).index === 2, "valid selection");
assert(transitionQueue(state, { type: "select", index: -1 }).index === 0, "negative selection leaves state unchanged");
assert(transitionQueue(state, { type: "select", index: 3 }).index === 0, "out-of-range selection leaves state unchanged");
assert(transitionQueue(state, { type: "select", index: 1.5 }).index === 0, "noninteger selection leaves state unchanged");

const empty: QueueState = { trackIds: [], index: -1, playing: false };
equal(transitionQueue(empty, { type: "next" }), { trackIds: [], index: -1, playing: false }, "next on empty queue");
equal(transitionQueue(empty, { type: "previous" }), { trackIds: [], index: -1, playing: false }, "previous on empty queue");
equal(transitionQueue(empty, { type: "select", index: 0 }), { trackIds: [], index: -1, playing: false }, "select on empty queue");
equal(transitionQueue(empty, { type: "toggle" }), { trackIds: [], index: -1, playing: true }, "toggle on empty queue");

rangeError(() => transitionQueue({ trackIds: [], index: 0, playing: false }, { type: "next" }), "malformed empty state");
rangeError(() => transitionQueue({ trackIds: ["a"], index: -1, playing: false }, { type: "toggle" }), "negative nonempty index");
rangeError(() => transitionQueue({ trackIds: ["a"], index: 1, playing: false }, { type: "next" }), "out-of-range index");
rangeError(() => transitionQueue({ trackIds: ["a"], index: 0.5, playing: false }, { type: "select", index: 0 }), "noninteger state index");
rangeError(() => transitionQueue({ trackIds: ["a", ""], index: 0, playing: false }, { type: "toggle" }), "stored empty track ID");

